from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    result = []  # Initialize an empty list to store the individual strings
    stack = []  # Stack to keep track of nested parentheses

    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if len(stack) == 1:
                result.append(paren_string[stack[0]:i+1])
                stack.pop()
            else:
                stack.pop()

    return result

